INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (7614, 'Hướng dẫn viết tầm nhìn kinh doanh', 'huong-dan-viet-tam-nhin-kinh-doanh', '		<div data-elementor-type="wp-post" data-elementor-id="7614" class="elementor elementor-7614" data-elementor-post-type="post">
				<div class="elementor-element elementor-element-e4ada0a e-con-full e-flex e-con e-parent" data-id="e4ada0a" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-63dbbbc e-con-full e-flex e-con e-parent" data-id="63dbbbc" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
		<div class="elementor-element elementor-element-9b26143 e-flex e-con-boxed e-con e-parent" data-id="9b26143" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
					<div class="e-con-inner">
		<div class="elementor-element elementor-element-fc37760 e-flex e-con-boxed e-con e-parent" data-id="fc37760" data-element_type="container" data-settings="{&quot;jet_parallax_layout_list&quot;:[]}">
